import{_ as i,o as e,c as a,a6 as t}from"./chunks/framework.ZMCvXf1_.js";const g=JSON.parse('{"title":"noorm — Write SQL. Skip the ORM.","titleTemplate":false,"description":"A SQL-first schema and change manager for Postgres, MySQL, SQLite, and MSSQL. Your schema lives in SQL files. noorm builds it, versions it, and keeps every environment in sync.","frontmatter":{"layout":"home","title":"noorm — Write SQL. Skip the ORM.","titleTemplate":false,"description":"A SQL-first schema and change manager for Postgres, MySQL, SQLite, and MSSQL. Your schema lives in SQL files. noorm builds it, versions it, and keeps every environment in sync.","hero":{"name":"noorm","text":"Write SQL. Skip the ORM.","tagline":"The raw SQL manager people keep asking for. Schema in files, changes in git, one CLI to prod.","actions":[{"theme":"brand","text":"Get started  →","link":"/getting-started/installation"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/noormdev/noorm"}]},"features":[{"icon":{"src":"/icons/database.svg"},"title":"Schema lives in SQL files","details":"Your SQL files are the current schema. Fresh databases build from them in seconds. Existing ones catch up through versioned changes.","link":"/getting-started/concepts","linkText":"How it works"},{"icon":{"src":"/icons/cubes.svg"},"title":"Real relational design","details":"Compound keys, inherited keys, check constraints, subtype clusters. Model what your data actually is instead of one surrogate ID per table.","link":"/guide/relational-design","linkText":"The case for it"},{"icon":{"src":"/icons/git-branch.svg"},"title":"Procedures, functions, TVFs","details":"Call stored procedures from TypeScript with typed params and result rows. Table-valued parameters included. The bridge ORMs never built.","link":"/reference/sdk#stored-procedures-functions-tvfs","linkText":"SDK reference"},{"icon":{"src":"/icons/fast-forward.svg"},"title":"Data pipelines","details":"Move data between databases in foreign-key order, across dialects, or out to portable files. Seed a QA environment from staging in one command.","link":"/guide/database/transfer","linkText":"Transfer data"},{"icon":{"src":"/icons/lock.svg"},"title":"Safe to point an agent at","details":"An MCP server exposes noorm to coding agents behind per-channel access roles. Admin at your terminal, read-only for the agent, invisible for prod.","link":"/guide/automation/mcp","linkText":"AI integration"},{"icon":{"src":"/icons/toolbox.svg"},"title":"One CLI, not five tabs","details":"Schema explorer, SQL terminal, encrypted vault, dynamic templates. Every command runs headless and emits JSON you can pipe into CI.","link":"/headless","linkText":"CLI reference"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),n={name:"index.md"};function l(h,s,r,o,p,d){return e(),a("div",null,[...s[0]||(s[0]=[t(`<h2 id="why-noorm" tabindex="-1">Why noorm? <a class="header-anchor" href="#why-noorm" aria-label="Permalink to “Why noorm?”">​</a></h2><p>Migration tools make you describe your schema twice: once in the migrations that built it, and once in your head. The current state only exists if you replay every file in order, and the moment you need a compound key or a trigger you are writing raw SQL inside a wrapper that was designed to keep you away from it.</p><p>noorm inverts that. <strong>Your SQL files are the current schema.</strong> A fresh database runs them and is done. An existing database gets to the same place through <strong>changes</strong> — small forward/revert pairs that noorm tracks, checksums, and applies in order.</p><p>Everything else follows from that split:</p><ul><li><strong>Stages</strong> keep dev, staging, and production configs apart, with access roles per environment</li><li><strong>Templates</strong> let one SQL file render differently per environment</li><li><strong>The SDK</strong> wraps it all in a type-safe client — Kysely queries, stored procedures, and TVFs</li><li><strong>Headless mode</strong> makes every command scriptable, with <code>--json</code> on anything worth parsing</li></ul><p>noorm is the fifth attempt at this problem, and every feature in it exists because working without an ORM was worse without it. <a href="/why-noorm.html">Why noorm</a> is the longer version of that story.</p><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to “Quick start”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install (no sudo needed)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://noorm.dev/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or via npm</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @noormdev/cli</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Bootstrap a project</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /my/project</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Corporate network?</p><p>If <code>noorm.dev</code> is blocked, install from the GitHub mirror:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/noormdev/noorm/master/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div></div><p>Write a SQL file, then build it:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sql/01_tables</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;CREATE TABLE users (id SERIAL PRIMARY KEY, name TEXT);&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sql/01_tables/001_users.sql</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>✓ Executed 1 file</span></span></code></pre></div><p>When the schema evolves, update the SQL file <strong>and</strong> add a change. The file keeps describing what the schema is; the change tells existing databases how to catch up:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Edit sql/01_tables/001_users.sql to add an email column</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Add changes/2024-01-add-email/forward.sql</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> change</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ff</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # fast-forward: apply pending changes</span></span></code></pre></div><p>A fresh database skips all of that — it just runs the files:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> use</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # fresh DB gets the current schema directly</span></span></code></pre></div><p><strong>SQL files = current schema. Changes = how existing databases get there.</strong></p><p>Setup wizards (<code>config add</code>, <code>config edit</code>, secret management) run in the TUI — launch it with <code>noorm ui</code>. Everything else runs headless:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # Build the schema from SQL files</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> change</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ff</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # Apply all pending changes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> explore</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # Inspect the database as JSON</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Push a team secret to the encrypted vault</span></span></code></pre></div><h2 id="plan-it-before-you-build-it" tabindex="-1">Plan it before you build it <a class="header-anchor" href="#plan-it-before-you-build-it" aria-label="Permalink to “Plan it before you build it”">​</a></h2><p>Most schemas get designed while they are being built, one migration at a time, and nobody outside the code can see the shape until it is already in production.</p><p><a href="/modeling/">ignatius</a> is the planning half. Describe your entities and processes in markdown and it renders an IDEF1X entity diagram, a searchable data dictionary, and SSADM data flow diagrams that show how data moves between people, the database, caches, files, and paper. Export it to a single HTML file, get agreement from the people who care, then hand the same markdown to your agent as the specification for the SQL.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/noormdev/ignatius/main/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ignatius</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./models</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span></span></code></pre></div><p>ignatius decides what the data is. noorm builds it. Both keep the source of truth in files you own. See <a href="/modeling/">Information modeling</a>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next steps”">​</a></h2><div class="next-steps"><p><a href="/getting-started/installation.html"><strong>Installation</strong></a> Get noorm installed and running.</p><p><a href="/getting-started/first-build.html"><strong>First Build</strong></a> Complete the tutorial and see the core value.</p><p><a href="/getting-started/building-your-sdk.html"><strong>Building Your SDK</strong></a> Create a type-safe database package for your apps.</p><p><a href="/modeling/"><strong>Information Modeling</strong></a> Design the data model before you write the schema.</p></div>`,26)])])}const c=i(n,[["render",l]]);export{g as __pageData,c as default};
